// Package auth implements the two authentication providers of
// ibkr-cli behind one interface (docs/SPEC.md §3):
//
//   - Mode G (gateway): talk to a local Client Portal Gateway whose
//     login, 2FA, and session maintenance are owned by IBeam. The CLI
//     never sees the IBKR password.
//   - Mode O (oauth): sign requests directly with IBKR's OAuth 1.0a
//     variant; no gateway process. The crypto lives in oauth1a.go and
//     is a port of IBind's implementation, verified against vectors
//     generated by that implementation.
//
// Both providers expose a base URL and an http.RoundTripper; the
// cpapi client is built from those, so commands are identical in
// both modes.
package auth

import (
	"context"
	"net/http"

	"github.com/rayli09/ibkr-cli/internal/config"
)

// SessionState summarises session health for `auth status`.
type SessionState struct {
	// Authenticated: the outer/primary authentication is valid.
	Authenticated bool
	// BrokerageLive: the brokerage session (needed for /iserver/*)
	// is established.
	BrokerageLive bool
	// Competing: another platform holds a competing session for the
	// same username (SPEC §3: sessions kick each other).
	Competing  bool
	ServerName string
	Detail     string
}

// Provider is the AuthProvider interface from SPEC §3.
type Provider interface {
	Transport() http.RoundTripper
	BaseURL() string
	Status(ctx context.Context) (SessionState, error)
	// EnsureSession makes a best effort to reach a live brokerage
	// session (tickle/reauthenticate, or the OAuth LST + ssodh/init
	// flow) and reports a SessionError when it cannot.
	EnsureSession(ctx context.Context) error
}

// New builds the provider for the configured mode.
func New(cfg *config.Config) (Provider, error) {
	if cfg.AuthMode() == config.ModeOAuth {
		return NewOAuthProvider(cfg), nil
	}
	return NewGatewayProvider(cfg), nil
}
